/**
 * Whole-catalog aggregate numbers, computed once at module load.
 *
 * The shop category pages (`/shop/<category>/`) only ever render and search
 * their own category's products, so they hand `ShopView` just that slice
 * instead of the full ~1,350-product array — which was serializing the
 * entire catalog (~1.5 MB) into every category page's HTML and tripping
 * Bing's "HTML size is too long" notice. `ShopView` still needs the
 * catalog-wide totals for its sidebar category/subcategory counts, the
 * header allocation count, and the price-slider ceiling, so those small
 * derived numbers travel via this object (~4 KB) instead.
 */
export const CATALOG_STATS: CatalogStats = (() => {
  const categoryCounts: Record<string, number> = {};
  const subcategoryCounts: Record<string, number> = {};
  let maxPrice = 0;
  for (const p of PRODUCTS) {
    categoryCounts[p.category] = (categoryCounts[p.category] || 0) + 1;
    if (p.subcategory) {
      subcategoryCounts[p.subcategory] = (subcategoryCounts[p.subcategory] || 0) + 1;
    }
    if (p.price > maxPrice) maxPrice = p.price;
  }
  return { total: PRODUCTS.length, maxPrice, categoryCounts, subcategoryCounts };
})();
